package com.voltflow.service;
import com.voltflow.entity.*; import com.voltflow.exception.NotFoundException; import com.voltflow.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.List;
@Service @RequiredArgsConstructor
public class ChargerService { private final ChargerRepository chargers;private final StationRepository stations; public List<Charger> list(Long stationId){return stationId==null?chargers.findAll():chargers.findByStationId(stationId);} @Transactional public Charger create(Charger c,Long stationId){c.setStation(stations.findById(stationId).orElseThrow(()->new NotFoundException("Station not found")));return chargers.save(c);} @Transactional public Charger update(Long id,Charger input){Charger c=chargers.findById(id).orElseThrow(()->new NotFoundException("Charger not found"));c.setConnectorType(input.getConnectorType());c.setPowerKw(input.getPowerKw());c.setStatus(input.getStatus());return c;} }
